static_output_instruction:
# Narrow
直接输出纯 JSON，绝对不要包含 markdown 代码块。
{
  "analyzed_events": [
    {
      "event_id": "保持输入一致",
      "is_valid_clinical_data": true,
      "matched_dimensions": [
        {
          "dimension_name": "具体HAMD-17维度名称或其他",
          "evidence_quote": "原文中的内容",
          "reasoning": "简短判定理由",
          "confidence_score": 0.00
        }
      ]
    }
  ]
}

# Narrow
Output pure JSON directly. Do not include Markdown code blocks.
{
"analyzed_events": [
{
"event_id": "same as input",
"is_valid_clinical_data": true,
"matched_items": [
{
"item_name": "specific PHQ-8 item name or other",
"evidence_quote": "original text content",
"reasoning": "brief judgment reason",
"confidence_score": 0.00
}
]
}
]
}

# Narrow
Output only a pure JSON object. Do not output Markdown code blocks.
{
"subject_id": "fill in the ID here",
"events": [
{
"event_id": "01",
"start_line": "[LXX]",
"end_line": "[LXX]"
}
]
}

# Narrow
仅输出纯 JSON 对象。不要输出 Markdown 代码块。
{
  "subject_id": "在此处填入ID",
  "events": [
    {
      "event_id": "01",
      "start_line": "[LXX]",
      "end_line": "[LXX]"
    }
  ]
}
